SELECT s0."rid_clients_client" AS "$k0", s0."f_client_preferred_name" AS "preferred_name" FROM "tbl_clients_client" AS s0 WHERE s0."f_client_archived_at" IS NULL AND s0."ref_client_owner" = :_scope AND ((SELECT COUNT(*) FROM "tbl_notes_note" AS j1 WHERE j1."ref_note_client" = s0."rid_clients_client" AND (j1."f_note_recorded_at" >= :after)) = 0) ORDER BY s0."rid_clients_client" ASC
